#!/usr/bin/env node
/**
 * check-token-parity.mjs — the DTCG↔CSS parity guard.
 *
 * Both tokens.dtc.json and dist/tokens.css are generated by gen-tokens.mjs from
 * theme-store.ts in one run, so they cannot legitimately drift. This gate fails
 * if a token in the DTCG export has no matching --p31-* custom property in the
 * CSS — which would mean the two generated artifacts were edited independently
 * or one emit path regressed.
 *
 * The reverse direction (a CSS token absent from the DTCG export) is legitimate:
 * non-portable values (calc/var/blur) are dropped from the DTCG export but kept
 * in CSS. So this is a one-way check, plus a drift report.
 */
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;
const DTCG = join(ROOT, 'packages', 'canon', 'tokens', 'tokens.dtc.json');
const CSS = join(ROOT, 'packages', 'canon', 'dist', 'tokens.css');

if (!existsSync(DTCG) || !existsSync(CSS)) {
  console.warn('check-token-parity SKIP — tokens.dtc.json or dist/tokens.css missing (run canon build first)');
  process.exit(0);
}

const dtcg = JSON.parse(readFileSync(DTCG, 'utf8'));
const p31 = dtcg.p31 ?? {};

// Flatten the p31 subtree (mixed groups + leaves) to a --p31-path → token map.
const flat = new Map();
const walk = (node, path) => {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    if (v && typeof v === 'object' && !Array.isArray(v) && v.$value === undefined) {
      walk(v, [...path, k]);
    } else {
      flat.set(`--p31-${[...path, k].join('-')}`, v);
    }
  }
};
walk(p31, []);

const cssText = readFileSync(CSS, 'utf8');
// [a-zA-Z0-9-] not [a-z0-9-]: one token (--p31-motion-shapeMorph-duration) is
// camelCase, a known naming inconsistency.
const cssKeys = new Set([...cssText.matchAll(/(--p31-[a-zA-Z0-9-]+)\s*:/g)].map((m) => m[1]));

const missing = [...flat.keys()].filter((k) => !cssKeys.has(k));

if (missing.length) {
  console.error('✗ check-token-parity: DTCG tokens missing from dist/tokens.css:');
  console.error('   ' + missing.join(', '));
  process.exit(1);
}

const cssOnly = [...cssKeys].filter((v) => !flat.has(v));
console.log(
  `✅ check-token-parity: ${flat.size} DTCG tokens all present in CSS (${cssOnly.length} CSS-only, non-portable)`,
);